commands.run:
docker exec -i dev-postgres-test-1 psql -X -v ON_ERROR_STOP=1 -U openvietgis -d openvietgis_test <<'SQL'
CREATE TABLE public.alembic_version (version_num text PRIMARY KEY);
INSERT INTO public.alembic_version VALUES ('e18-ci-fixture');
CREATE TABLE public.e18_fixture (
  id integer PRIMARY KEY, tenant text NOT NULL, payload text NOT NULL,
  geom geometry(Point,4326) NOT NULL
);
INSERT INTO public.e18_fixture VALUES
  (1,'a','first',ST_SetSRID(ST_MakePoint(106,10),4326)),
  (2,'b','second',ST_SetSRID(ST_MakePoint(107,11),4326));
ALTER TABLE public.e18_fixture ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.e18_fixture FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_fixture ON public.e18_fixture
  TO openvietgis_runtime
  USING (tenant = current_setting('app.e18_tenant',true));
GRANT SELECT ON public.e18_fixture TO openvietgis_runtime;
SQL

actual="$(docker exec -i dev-postgres-test-1 psql -X -qAt -v ON_ERROR_STOP=1 -U openvietgis -d ovg_rehearsal_ci_fixture <<'SQL'
SET ROLE openvietgis_runtime;
SET app.e18_tenant = 'a';
SELECT id || ':' || payload FROM public.e18_fixture ORDER BY id;
SET app.e18_tenant = 'unknown';
SELECT count(*) FROM public.e18_fixture;
SQL
)"
test "$actual" = "$(printf '1:first\n0')"

python3 - <<'PY'
import json
import subprocess
import sys

meta = json.loads(
    subprocess.check_output(["cargo", "metadata", "--format-version", "1", "--no-deps", "--locked"])
)
core_crates = {
    "ovg-core",
    "ovg-storage",
    "ovg-spatial",
    "ovg-sync",
    "ovg-processing",
    "ovg-module-sdk",
}
violations = []
for pkg in meta["packages"]:
    if pkg["name"] in core_crates:
        for dep in pkg["dependencies"]:
            dep_name = dep["name"]
            dep_path = dep.get("path") or ""
            if dep_name.startswith("ovg-module-") and dep_name != "ovg-module-sdk":
                violations.append(f"{pkg['name']} depends on vertical module {dep_name}")
            if "/modules/" in dep_path.replace("\\", "/"):
                violations.append(f"{pkg['name']} depends on path inside modules/: {dep_path}")
if violations:
    print("ARCHITECTURE ISOLATION VIOLATIONS:", file=sys.stderr)
    for v in violations:
        print(f"  - {v}", file=sys.stderr)
    sys.exit(1)
print("Architecture isolation check passed: core crates have zero dependencies on modules/.")
PY
